// CI must pass on a fresh runner: route types are generated by the typecheck itself, and the steps run
// in an order that needs nothing from an earlier build.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import pkg from '../package.json';

const workflow = readFileSync(new URL('../.github/workflows/ci.yml', import.meta.url), 'utf8');

test('`pnpm typecheck` generates the route types (PageProps, RouteContext) before tsc reads them', () => {
  assert.match(pkg.scripts.typecheck, /^next typegen && tsc --noEmit$/);
});

test('CI installs from the lockfile, then typechecks, tests and builds, in that order', () => {
  const runs = [...workflow.matchAll(/^\s*- run: (.+)$/gm)].map((m) => m[1].trim());
  assert.deepEqual(runs, ['pnpm install --frozen-lockfile', 'pnpm typecheck', 'pnpm test', 'pnpm build']);
});

test('every action is pinned to a full commit SHA', () => {
  const uses = [...workflow.matchAll(/uses: (\S+)/g)].map((m) => m[1]);
  assert.ok(uses.length >= 4);
  for (const u of uses) assert.match(u, /^[\w.-]+\/[\w.-]+@[0-9a-f]{40}$/, u);
});
